# Implementation plans

Plans turn an accepted specification into a reviewable sequence of small,
verifiable changes. They explain how to build the behavior; the linked
specification remains the source of truth for what the behavior must be.

Use the same kebab-case stem as the specification. A useful plan includes:

- a link to the accepted specification;
- the goal, non-goals, and assumptions relevant to implementation;
- ordered tasks with exact file paths;
- a failing test before each behavior change;
- the minimal implementation needed to pass that test;
- documentation and public-export updates;
- focused and full verification commands;
- a completion checklist updated as tasks land.

Prefer tasks that can be implemented and reviewed independently. Include short
code snippets when they remove ambiguity, but do not paste entire future files
into the plan.

See [`example-retry-policy.md`](example-retry-policy.md) for a test-first sample.

//! Integration tests for the public crate surface.
//!
//! These link against the crate as a downstream consumer would: they can only
//! use what `src/lib.rs` re-exports. Treat them as the regression suite for the
//! crate's public contract — if a change breaks a test here, it is a breaking
//! change for users.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyruntime_python::{
    CONTRACT_VERSION, DEFAULT_VERSION, Error, Language, PYTHON, distribution, harness, layout,
    names, parse_version, satisfies,
};

#[test]
fn the_provider_serves_the_shared_interface_from_the_contract() {
    assert_eq!(
        names::PROVIDER_INTERFACE,
        tinyruntime_python::PROVIDER_INTERFACE
    );
    assert_eq!(
        names::providers::PYTHON_OBJECT_PATH,
        names::object_path_for(names::providers::PYTHON)
    );
    assert_eq!(names::PROVIDER_METHODS.len(), 5);
    assert_eq!(Language::python().as_str(), PYTHON);
}

#[test]
fn the_contract_is_re_exported_so_consumers_take_one_dependency() {
    let same: tinyruntime_bus::WorkerHarness = harness();
    assert_eq!(same, harness());
    assert!(tinyruntime_python::is_compatible_with_contract());
    let _ = CONTRACT_VERSION;
}

#[test]
fn the_default_floor_is_one_this_crate_can_reason_about() {
    let floor = parse_version(DEFAULT_VERSION).expect("the default floor is a version");
    assert!(satisfies(floor, DEFAULT_VERSION, None));
}

#[test]
fn the_host_table_and_the_layout_agree_about_this_platform() {
    // A host the channel publishes for must also be one the layout knows the
    // shape of, or an install would succeed and then be unusable.
    if distribution::host_suffix().is_ok() {
        let scratch = tempfile::tempdir().unwrap();
        assert!(
            layout::find_interpreter(scratch.path()).is_none(),
            "an empty directory must not read as an install"
        );
        assert!(layout::TOOLS.contains(&"python"));
    }
}

#[test]
fn an_unsupported_host_is_reported_by_name() {
    let error = distribution::suffix_for("plan9", "x86_64").expect_err("no build exists");
    assert!(matches!(error, Error::UnsupportedHost { .. }));
}

//! End-to-end tests for the shipped worker harness, against a real `python`.
//!
//! The harness is the one part of this crate that is not Rust, so nothing else
//! in the suite can check that it actually speaks the protocol. These tests
//! stand in for the router: they listen on loopback, launch the harness the way
//! the router would, complete the handshake, and run jobs through it.
//!
//! They skip when the machine has no Python 3, so the suite stays hermetic on a
//! runner without one rather than failing for the wrong reason.

#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::PathBuf;
use std::process::Stdio;
use std::time::Duration;

use tokio::io::{AsyncBufReadExt, AsyncWriteExt, BufReader, Lines};
use tokio::net::{TcpListener, TcpStream};
use tokio::process::{Child, Command};

use tinyruntime_python::{WORKER_PROTOCOL_VERSION, harness};

/// How long any single step may take before the test gives up.
const STEP_TIMEOUT: Duration = Duration::from_secs(30);

/// Read and discard a child stream, so a job writing to it never blocks.
fn drain(stream: impl tokio::io::AsyncRead + Send + Unpin + 'static) {
    tokio::spawn(async move {
        let mut lines = BufReader::new(stream).lines();
        while let Ok(Some(_)) = lines.next_line().await {}
    });
}

/// The first working Python 3 on this machine, or `None`.
async fn interpreter() -> Option<String> {
    for candidate in ["python3", "python"] {
        let usable = Command::new(candidate)
            .arg("--version")
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .status()
            .await
            .is_ok_and(|status| status.success());
        if usable {
            return Some(candidate.to_string());
        }
    }
    None
}

/// A harness process under test, plus the protocol connection to it.
struct Harness {
    _child: Child,
    writer: tokio::io::WriteHalf<TcpStream>,
    lines: Lines<BufReader<tokio::io::ReadHalf<TcpStream>>>,
    _scratch: tempfile::TempDir,
    cwd: PathBuf,
}

impl Harness {
    /// Launch the harness the way the router would, or `None` without Python.
    async fn launch() -> Option<Self> {
        let Some(binary) = interpreter().await else {
            eprintln!("skipped: this machine has no usable python");
            return None;
        };

        let scratch = tempfile::tempdir().unwrap();
        let harness = harness();
        let script = scratch.path().join(&harness.filename);
        std::fs::write(&script, &harness.source).unwrap();

        let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let token = "test-secret-token";

        let mut command = Command::new(binary);
        command
            .args(harness.command_args(&script.to_string_lossy()))
            .env("TINYRUNTIME_PROTOCOL_ADDR", address.to_string())
            .env("TINYRUNTIME_PROTOCOL_TOKEN", token)
            .env("PATH", std::env::var("PATH").unwrap_or_default());
        for (name, value) in &harness.env {
            command.env(name, value);
        }
        let mut child = command
            .stdin(Stdio::null())
            .stdout(Stdio::piped())
            .stderr(Stdio::piped())
            .kill_on_drop(true)
            .spawn()
            .unwrap();

        let (stream, _) = tokio::time::timeout(STEP_TIMEOUT, listener.accept())
            .await
            .expect("the harness connected back")
            .unwrap();
        let (reader, writer) = tokio::io::split(stream);
        let mut lines = BufReader::new(reader).lines();

        let handshake: serde_json::Value = serde_json::from_str(
            &tokio::time::timeout(STEP_TIMEOUT, lines.next_line())
                .await
                .expect("the handshake arrived")
                .unwrap()
                .expect("the harness sent a handshake"),
        )
        .unwrap();

        assert_eq!(handshake["ready"], serde_json::json!(true));
        assert_eq!(
            handshake["protocol"],
            serde_json::json!(WORKER_PROTOCOL_VERSION)
        );
        assert_eq!(handshake["language"], serde_json::json!("python"));
        assert_eq!(
            handshake["token"],
            serde_json::json!(token),
            "the harness must echo the secret it was given"
        );

        // Drain the child's own descriptors, exactly as the router does. This is
        // not tidiness: a job that writes to fd 1 blocks once the pipe fills.
        if let Some(stdout) = child.stdout.take() {
            drain(stdout);
        }
        if let Some(stderr) = child.stderr.take() {
            drain(stderr);
        }

        let cwd = scratch.path().to_path_buf();
        Some(Self {
            _child: child,
            writer,
            lines,
            _scratch: scratch,
            cwd,
        })
    }

    /// Run one job and return its reply.
    async fn run(&mut self, id: &str, code: &str, timeout_ms: Option<u64>) -> serde_json::Value {
        let mut request = serde_json::json!({
            "id": id,
            "code": code,
            "cwd": self.cwd.to_string_lossy(),
        });
        if let Some(timeout_ms) = timeout_ms {
            request["timeout_ms"] = serde_json::json!(timeout_ms);
        }

        let mut line = serde_json::to_string(&request).unwrap();
        line.push('\n');
        self.writer.write_all(line.as_bytes()).await.unwrap();
        self.writer.flush().await.unwrap();

        let reply = tokio::time::timeout(STEP_TIMEOUT, self.lines.next_line())
            .await
            .expect("the harness replied")
            .unwrap()
            .expect("the harness sent a reply");
        let reply: serde_json::Value = serde_json::from_str(&reply).unwrap();
        assert_eq!(
            reply["id"],
            serde_json::json!(id),
            "reply was for another job"
        );
        reply
    }
}

#[tokio::test]
async fn the_harness_runs_a_job_and_reports_its_output() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness.run("1", "print(6 * 7)", None).await;
    assert_eq!(reply["ok"], serde_json::json!(true));
    assert_eq!(reply["stdout"], serde_json::json!("42\n"));
    assert_eq!(reply["exit_code"], serde_json::json!(0));
}

#[tokio::test]
async fn one_warm_worker_serves_many_jobs() {
    // The entire reason the pool exists. If the harness exited after a job, this
    // would fail on the second one.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    for index in 0..3 {
        let reply = harness
            .run(&index.to_string(), &format!("print({index} + 1)"), None)
            .await;
        assert_eq!(
            reply["stdout"],
            serde_json::json!(format!("{}\n", index + 1))
        );
    }
}

#[tokio::test]
async fn each_job_gets_fresh_globals() {
    // The only isolation a Python worker can offer. Without it, a name defined
    // by one job would be visible to an unrelated later one.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    harness
        .run("1", "leaked = 'from the first job'", None)
        .await;

    let reply = harness.run("2", "print('leaked' in dir())", None).await;
    assert_eq!(reply["stdout"], serde_json::json!("False\n"));
}

#[tokio::test]
async fn a_job_that_raises_reports_a_traceback_without_killing_the_worker() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let raised = harness.run("1", "raise ValueError('boom')", None).await;
    assert_eq!(
        raised["ok"],
        serde_json::json!(true),
        "the harness ran it; the job failed"
    );
    assert_eq!(raised["exit_code"], serde_json::json!(1));
    assert!(raised["stderr"].as_str().unwrap().contains("boom"));

    let after = harness.run("2", "print('still here')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("still here\n"));
}

#[tokio::test]
async fn a_job_calling_sys_exit_reports_its_code_and_leaves_the_worker_running() {
    // A long-lived worker must survive `sys.exit(3)`. Without the SystemExit
    // arm the interpreter would exit and take every queued job with it.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let exited = harness.run("1", "import sys; sys.exit(3)", None).await;
    assert_eq!(exited["exit_code"], serde_json::json!(3));

    let after = harness.run("2", "print('survived')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("survived\n"));
}

#[tokio::test]
async fn output_written_past_the_python_layer_is_still_captured() {
    // `os.write(1, ...)` bypasses `sys.stdout` entirely. If capture were not at
    // the file-descriptor level this would land on the real descriptor instead
    // of in the reply.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run("1", "import os; os.write(1, b'LOW_LEVEL')", None)
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("LOW_LEVEL"));
}

#[tokio::test]
async fn a_subprocess_started_by_a_job_is_captured_too() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            "import subprocess, sys; subprocess.run([sys.executable, '-c', \"print('FROM_CHILD')\"])",
            None,
        )
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("FROM_CHILD\n"));
}

#[tokio::test]
async fn relative_paths_resolve_against_the_job_directory() {
    // A shared warm worker runs wherever the last job left it unless the harness
    // enters each job's directory. Getting this wrong escapes the caller's sandbox.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    std::fs::write(harness.cwd.join("probe.txt"), b"RELATIVE_OK").unwrap();

    let reply = harness
        .run("1", "print(open('./probe.txt').read(), end='')", None)
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("RELATIVE_OK"));
}

#[tokio::test]
async fn a_job_whose_directory_is_missing_fails_rather_than_running_elsewhere() {
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let sentinel = harness.cwd.join("must-not-exist.txt");
    harness.cwd = harness.cwd.join("deleted-sandbox");

    let reply = harness
        .run(
            "1",
            "open('must-not-exist.txt', 'w').write('escaped')",
            None,
        )
        .await;
    assert_eq!(reply["ok"], serde_json::json!(false), "the job ran anyway");
    assert!(
        reply["error"]
            .as_str()
            .unwrap()
            .contains("failed to set worker cwd")
    );
    assert!(!sentinel.exists(), "the job escaped its sandbox");
}

#[tokio::test]
async fn the_working_directory_is_restored_between_jobs() {
    // Jobs share one interpreter, so a job that changed directory and was not
    // restored would silently relocate every job after it.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    std::fs::create_dir(harness.cwd.join("elsewhere")).unwrap();
    harness
        .run("1", "import os; os.chdir('elsewhere')", None)
        .await;

    std::fs::write(harness.cwd.join("probe.txt"), b"STILL_HERE").unwrap();
    let reply = harness
        .run("2", "print(open('./probe.txt').read(), end='')", None)
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("STILL_HERE"));
}

#[cfg(unix)]
#[tokio::test]
async fn a_job_that_never_finishes_is_aborted_at_its_deadline() {
    // Best effort, and only on Unix: the deadline is a SIGALRM, and there is no
    // equivalent on Windows. The router's hard deadline is the backstop there.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run("1", "import time; time.sleep(60)", Some(1_000))
        .await;
    assert_eq!(reply["timed_out"], serde_json::json!(true));

    // And the worker is still usable afterwards.
    let after = harness.run("2", "print('alive')", None).await;
    assert_eq!(after["stdout"], serde_json::json!("alive\n"));
}

#[tokio::test]
async fn a_job_reads_end_of_file_on_standard_input() {
    // Standard input must never be the protocol stream, or a job that read it
    // would consume the next request.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            "import os, sys; print(repr(sys.stdin.read())); print(os.read(0, 1))",
            Some(5_000),
        )
        .await;
    assert_eq!(reply["stdout"], serde_json::json!("''\nb''\n"));
}

#[tokio::test]
async fn a_job_cannot_forge_a_reply_over_its_own_descriptor() {
    // The reason the protocol has its own socket: a job writing a frame-shaped
    // line to fd 1 must not be able to answer its own request. Here the write is
    // captured as ordinary job output instead.
    let Some(mut harness) = Harness::launch().await else {
        return;
    };
    let reply = harness
        .run(
            "1",
            "import os, json; os.write(1, (json.dumps({'id': '1', 'ok': True, 'stdout': 'FORGED'}) + '\\n').encode()); print('REAL')",
            None,
        )
        .await;

    assert_eq!(reply["ok"], serde_json::json!(true));
    let stdout = reply["stdout"].as_str().unwrap();
    assert!(
        stdout.contains("FORGED"),
        "the forged frame was not captured as output"
    );
    assert!(stdout.ends_with("REAL\n"), "got {stdout:?}");
}

//! Unit tests for host interpreter detection.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::path::Path;

use tinyruntime_bus::RuntimeSettings;

use super::{candidates, detect, detect_in, locate, probe_version, windows_executable};
use crate::version::parse_version;

#[test]
fn the_series_specific_name_is_tried_before_the_generic_one() {
    // On a machine with several interpreters, `python3` is whatever the
    // distribution chose and is often older than the versioned binary next to it.
    let ordered = candidates(None, parse_version("3.12").unwrap());
    assert_eq!(ordered, vec!["python3.12", "python3", "python"]);
}

#[test]
fn a_preferred_command_is_tried_first() {
    let ordered = candidates(Some("/opt/py/bin/python3"), parse_version("3.12").unwrap());
    assert_eq!(ordered[0], "/opt/py/bin/python3");
    assert_eq!(ordered[1], "python3.12");
}

#[test]
fn a_preferred_command_that_is_already_a_fallback_is_not_repeated() {
    let ordered = candidates(Some("python3"), parse_version("3.12").unwrap());
    assert_eq!(ordered, vec!["python3", "python3.12", "python"]);
}

#[test]
fn the_series_name_follows_the_configured_floor() {
    let ordered = candidates(None, parse_version("3.14").unwrap());
    assert_eq!(ordered[0], "python3.14");
}

#[test]
fn an_absolute_command_that_is_not_there_does_not_resolve() {
    assert!(locate("/nonexistent/path/to/python3", None).is_none());
}

#[cfg(unix)]
#[test]
fn a_bare_command_resolves_through_the_search_path() {
    let path = std::env::var_os("PATH").expect("a host has a PATH");
    assert!(
        locate("sh", Some(&path)).is_some(),
        "PATH lookup found nothing at all"
    );
}

#[test]
fn a_bare_command_with_no_search_path_does_not_resolve() {
    assert!(locate("python3", None).is_none());
}

#[test]
fn the_windows_executable_lookup_is_checked_everywhere() {
    let scratch = tempfile::tempdir().expect("scratch directory");
    let named = scratch.path().join("python.exe");
    std::fs::write(&named, b"binary").expect("the file writes");
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        std::fs::set_permissions(&named, std::fs::Permissions::from_mode(0o755)).unwrap();
    }

    assert_eq!(
        windows_executable(scratch.path(), "python", true),
        Some(named)
    );
    assert_eq!(
        windows_executable(scratch.path(), "python", false),
        None,
        "the lookup must not fire off Windows"
    );
}

/// Write an executable standing in for an interpreter, printing `version`.
///
/// Waits until the script actually runs before returning. A file written and
/// immediately executed can transiently fail — the kernel may still see a writer
/// on it — and a failed probe is reported as "no interpreter", which would
/// surface as a confusing assertion failure rather than as the flake it is.
#[cfg(unix)]
fn fake_python(directory: &Path, name: &str, version: &str) -> std::path::PathBuf {
    use std::os::unix::fs::PermissionsExt;

    let path = directory.join(name);
    std::fs::write(&path, format!("#!/bin/sh\necho '{version}'\n")).expect("the script writes");
    std::fs::set_permissions(&path, std::fs::Permissions::from_mode(0o755))
        .expect("the script is executable");

    for _ in 0..50 {
        if std::process::Command::new(&path)
            .arg("--version")
            .output()
            .is_ok_and(|out| out.status.success())
        {
            return path;
        }
        std::thread::sleep(std::time::Duration::from_millis(20));
    }
    panic!(
        "the fake interpreter at {} never became runnable",
        path.display()
    );
}

#[cfg(unix)]
#[tokio::test]
async fn an_interpreter_inside_the_range_is_reused() {
    let scratch = tempfile::tempdir().expect("scratch directory");
    fake_python(scratch.path(), "python3", "Python 3.13.1");

    let path = std::ffi::OsString::from(scratch.path());
    let layout = detect_in(&RuntimeSettings::new("3.12"), Some(&path))
        .await
        .expect("a newer interpreter satisfies a floor");
    assert_eq!(layout.version, "3.13.1");
    assert!(layout.executable("python").is_some());
}

#[cfg(unix)]
#[tokio::test]
async fn the_series_specific_name_is_preferred_over_the_generic_one() {
    // On a machine with both, `python3` is often the older one.
    let scratch = tempfile::tempdir().expect("scratch directory");
    fake_python(scratch.path(), "python3", "Python 3.12.0");
    fake_python(scratch.path(), "python3.14", "Python 3.14.1");

    let path = std::ffi::OsString::from(scratch.path());
    let layout = detect_in(&RuntimeSettings::new("3.14"), Some(&path))
        .await
        .expect("the versioned binary is found");
    assert_eq!(layout.version, "3.14.1");
}

#[cfg(unix)]
#[tokio::test]
async fn an_interpreter_below_the_floor_is_not_reused() {
    let scratch = tempfile::tempdir().expect("scratch directory");
    fake_python(scratch.path(), "python3", "Python 3.11.9");

    let path = std::ffi::OsString::from(scratch.path());
    assert!(
        detect_in(&RuntimeSettings::new("3.12"), Some(&path))
            .await
            .is_none()
    );
}

#[cfg(unix)]
#[tokio::test]
async fn an_interpreter_that_prints_nothing_useful_is_skipped() {
    let scratch = tempfile::tempdir().expect("scratch directory");
    fake_python(scratch.path(), "python3", "not-a-version");

    let path = std::ffi::OsString::from(scratch.path());
    assert!(
        detect_in(&RuntimeSettings::new("3.12"), Some(&path))
            .await
            .is_none()
    );
}

#[cfg(unix)]
#[tokio::test]
async fn a_binary_that_does_not_understand_the_flag_is_not_an_interpreter() {
    if !Path::new("/bin/false").exists() {
        return;
    }
    assert!(probe_version(Path::new("/bin/false")).await.is_none());
}

#[tokio::test]
async fn a_binary_that_is_not_there_is_not_probed_successfully() {
    assert!(
        probe_version(Path::new("/nonexistent/python3"))
            .await
            .is_none()
    );
}

#[tokio::test]
async fn an_unparseable_floor_detects_nothing() {
    assert!(detect(&RuntimeSettings::new("latest")).await.is_none());
}

#[tokio::test]
async fn a_ceiling_below_everything_installed_detects_nothing() {
    // Even on a machine with Python, a range nothing satisfies must come back
    // empty rather than handing over an interpreter outside it.
    let mut settings = RuntimeSettings::new("3.0");
    settings.maximum_version = "3.1".to_string();
    assert!(
        detect(&settings).await.is_none(),
        "an interpreter outside the requested range was accepted"
    );
}

//! Unit tests for the Python install layout.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use std::fs;
use std::path::Path;

use tinyruntime_bus::RuntimeSettings;

use super::{find_interpreter, from_parts};

/// Build an unpacked standalone build with the named files in its bin directory.
fn fabricate(root: &Path, files: &[&str]) -> std::path::PathBuf {
    let bin = if cfg!(windows) {
        root.join("python")
    } else {
        root.join("python").join("bin")
    };
    fs::create_dir_all(&bin).unwrap();
    for file in files {
        fs::write(bin.join(file), b"").unwrap();
    }
    bin
}

#[cfg(unix)]
#[test]
fn the_interpreter_is_found_inside_the_channels_python_directory() {
    // Every standalone build, of every version, unpacks into `python/`.
    let scratch = tempfile::tempdir().unwrap();
