    // than letting the version bounds decide.
    assert_eq!(version("3.13.0rc1").to_string(), "3.13.0");
    assert_eq!(version("3.13.2b1").to_string(), "3.13.2");
}

#[test]
fn something_that_is_not_a_version_does_not_parse() {
    assert_eq!(parse_version("latest"), None);
    assert_eq!(
        parse_version("3"),
        None,
        "a bare major is not a python version"
    );
    assert_eq!(parse_version(""), None);
}

#[test]
fn versions_order_by_component_rather_than_lexically() {
    // The bug this rules out: `3.9` sorting above `3.12` as text.
    assert!(version("3.12.0") > version("3.9.20"));
    assert!(version("3.12.10") > version("3.12.9"));
    assert!(version("4.0.0") > version("3.99.99"));
}

#[test]
fn a_request_names_a_floor_rather_than_an_exact_version() {
    assert!(satisfies(version("3.12.4"), "3.12", None));
    assert!(
        satisfies(version("3.13.1"), "3.12", None),
        "newer satisfies a floor"
    );
    assert!(!satisfies(version("3.11.9"), "3.12", None));
}

#[test]
fn an_exclusive_ceiling_keeps_selection_off_a_newer_series() {
    // The case this exists for: pre-releases of a newer series sitting in the
    // same index as the builds actually wanted.
    assert!(satisfies(version("3.14.1"), "3.12", Some("3.15")));
    assert!(!satisfies(version("3.15.0"), "3.12", Some("3.15")));
    assert!(
        !satisfies(version("3.15.0"), "3.12", Some("3.15")),
        "the ceiling is exclusive, so 3.15.0 itself is out"
    );
}

#[test]
fn a_blank_ceiling_is_no_ceiling() {
    assert!(satisfies(version("3.99.0"), "3.12", Some("")));
    assert!(satisfies(version("3.99.0"), "3.12", Some("   ")));
    assert!(satisfies(version("3.99.0"), "3.12", None));
}

#[test]
fn a_floor_that_is_not_a_version_accepts_nothing() {
    // A misconfigured floor must not quietly install whatever came first.
    assert!(!satisfies(version("3.12.4"), "latest", None));
}

#[test]
fn a_ceiling_that_is_not_a_version_accepts_nothing() {
    assert!(!satisfies(version("3.12.4"), "3.12", Some("nonsense")));
}

//! Unit tests for the crate-wide error type.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use super::Error;

#[test]
fn messages_are_lowercase_and_unpunctuated() {
    let errors = [
        Error::UnsupportedHost {
            os: "plan9".to_string(),
            arch: "x86_64".to_string(),
        },
        Error::InvalidVersion {
            value: "latest".to_string(),
            bound: "minimum",
        },
        Error::IndexUnavailable("the request timed out".to_string()),
        Error::NoMatchingBuild {
            release: "20240909".to_string(),
            bounds: ">= 3.12".to_string(),
        },
    ];
    for error in errors {
        let rendered = error.to_string();
        assert!(
            !rendered.ends_with('.'),
            "`{rendered}` ends with punctuation"
        );
        let first = rendered.chars().next().expect("a non-empty message");
        assert!(!first.is_uppercase(), "`{rendered}` starts with a capital");
    }
}

#[test]
fn an_unreadable_index_and_an_empty_one_are_different_errors() {
    // They call for different responses: one is worth retrying, the other means
    // the version bounds excluded everything the channel actually publishes.
    let unreadable = Error::IndexUnavailable("the connection failed".to_string()).to_string();
    let empty = Error::NoMatchingBuild {
        release: "20240909".to_string(),
        bounds: ">= 3.99".to_string(),
    }
    .to_string();
    assert!(
        unreadable.contains("could not be read"),
        "got `{unreadable}`"
    );
    assert!(empty.contains("no build matching"), "got `{empty}`");
    assert!(
        empty.contains(">= 3.99"),
        "the bounds that excluded everything are named"
    );
}

#[test]
fn an_invalid_bound_says_which_bound_it_was() {
    let rendered = Error::InvalidVersion {
        value: "nonsense".to_string(),
        bound: "maximum",
    }
    .to_string();
    assert!(rendered.contains("maximum"), "got `{rendered}`");
    assert!(rendered.contains("`nonsense`"), "got `{rendered}`");
}

//! Unit tests for the shipped harness.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use tinyruntime_bus::WORKER_PROTOCOL_VERSION;

use super::{FILENAME, SOURCE, harness};

#[test]
fn the_harness_runs_under_python_and_speaks_this_protocol() {
    let harness = harness();
    assert_eq!(harness.executable, "python");
    assert_eq!(harness.filename, FILENAME);
    assert_eq!(
        harness.protocol_version, WORKER_PROTOCOL_VERSION,
        "a harness on another protocol is refused at the handshake"
    );
}

#[test]
fn output_is_unbuffered_by_both_the_flag_and_the_environment() {
    // Without these a job's output can sit in a buffer until the process exits,
    // which for a worker that never exits means it is never seen at all.
    let harness = harness();
    assert!(harness.args_before_script.contains(&"-u".to_string()));
    assert!(
        harness
            .env
            .contains(&("PYTHONUNBUFFERED".to_string(), "1".to_string()))
    );
    assert_eq!(
        harness
            .command_args("/cache/pool_worker.py")
            .last()
            .map(String::as_str),
        Some("/cache/pool_worker.py"),
        "the script must come after the flags"
    );
}

#[test]
fn the_harness_announces_the_protocol_version_this_build_speaks() {
    // The script's constant and the contract's are two separate declarations of
    // one number; a mismatch fails every handshake at runtime.
    assert!(
        SOURCE.contains(&format!("PROTOCOL_VERSION = {WORKER_PROTOCOL_VERSION}")),
        "the harness declares a different protocol version than the contract"
    );
}

#[test]
fn the_harness_reads_the_protocol_environment_the_router_sets() {
    assert!(SOURCE.contains("TINYRUNTIME_PROTOCOL_ADDR"));
    assert!(SOURCE.contains("TINYRUNTIME_PROTOCOL_TOKEN"));
}

#[test]
fn output_is_captured_at_the_file_descriptor_level() {
    // Swapping `sys.stdout` would miss `os.write(1, ...)`, subprocess output,
    // and anything a native extension writes — all of which would then land on
    // whatever the real descriptor points at.
    assert!(
        SOURCE.contains("os.dup2("),
        "capture is not descriptor-level"
    );
    assert!(
        SOURCE.contains("tempfile.TemporaryFile"),
        "a pipe would deadlock on a job that outproduces its buffer"
    );
}

#[test]
fn a_job_that_cannot_enter_its_directory_fails_rather_than_running_elsewhere() {
    assert!(SOURCE.contains("failed to set worker cwd"));
}

#[test]
fn a_job_calling_sys_exit_is_reported_rather_than_ending_the_worker() {
    // A long-lived worker must survive `sys.exit(3)`; the exit code belongs in
    // the reply instead.
    assert!(SOURCE.contains("except SystemExit"));
}
